contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, address log) public payable {
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertSetMinSum;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertSetMinSum = true; } else { revertSetMinSum = false; }

        bool revertSetLogFile;
        c.SetLogFile(log); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertSetLogFile = true; } else { revertSetLogFile = false; }

        assert(revertSetMinSum && revertSetLogFile);
    }

    receive() external payable {}
}

